design.custom_css:
/* "מורשים מטעם היבואן" band. DOM order: 1 = the המחלקה הראשונה badge, 2-5 = Mazda, Ford, Dongfeng, Voyah.
   Desktop (RTL, column 1 = rightmost): badge | text | 2x2 of the four marques (Mazda Ford / Dongfeng Voyah read
   left to right, the order the spec asks for). The row wrapper melts away so the chips sit on the band's own grid.
   The logo files are cropped to their visible area, so the marks fill their chips instead of floating in padding. */
.elementor .e-con.zs-logos.zs-v-band .zs-logos__band, .zs-logos.zs-v-band .e-con.zs-logos__band { grid-template-columns: minmax(0, 1fr) minmax(0, 1.9fr) repeat(2, minmax(0, 1fr)); grid-auto-rows: auto; align-items: center; gap: 20px clamp(20px, 2.5vw, 36px); }
body .elementor .zs-logos.zs-v-band .e-con.zs-logos__row { display: contents; }
body .zs-logos.zs-v-band .zs-logos__head { grid-column: 2; grid-row: 1 / span 2; }
body .zs-logos.zs-v-band .zs-logos__img { display: flex; align-items: center; justify-content: center; box-sizing: border-box; background: #fff; border-radius: var(--r); width: 100%; height: 124px; padding: 22px 28px; margin: 0; }
body .zs-logos.zs-v-band .zs-logos__img img { display: block; width: 100%; height: 100%; max-height: none; padding: 0; background: none; border-radius: 0; object-fit: contain; filter: none; opacity: 1; }
body .zs-logos.zs-v-band .zs-logos__img:nth-child(1) { grid-column: 1; grid-row: 1 / span 2; height: 150px; }
body .zs-logos.zs-v-band .zs-logos__img:nth-child(2) { grid-column: 4; grid-row: 1; }
body .zs-logos.zs-v-band .zs-logos__img:nth-child(3) { grid-column: 3; grid-row: 1; }
body .zs-logos.zs-v-band .zs-logos__img:nth-child(4) { grid-column: 4; grid-row: 2; }
body .zs-logos.zs-v-band .zs-logos__img:nth-child(5) { grid-column: 3; grid-row: 2; }
@media (max-width: 900px) {
  /* phones: text, the badge, then the 2x2 (same left-to-right order); two columns, chips never narrower than ~150px */
  .elementor .e-con.zs-logos.zs-v-band .zs-logos__band, .zs-logos.zs-v-band .e-con.zs-logos__band { grid-template-columns: repeat(2, minmax(0, 1fr)); gap: 14px; }
  body .zs-logos.zs-v-band .zs-logos__head { grid-column: 1 / -1; grid-row: 1; }
  body .zs-logos.zs-v-band .zs-logos__img { height: 92px; padding: 14px 16px; }
  body .zs-logos.zs-v-band .zs-logos__img:nth-child(1) { grid-column: 1 / -1; grid-row: 2; justify-self: center; width: min(100%, 260px); height: 110px; }
  body .zs-logos.zs-v-band .zs-logos__img:nth-child(2) { grid-column: 2; grid-row: 3; }
  body .zs-logos.zs-v-band .zs-logos__img:nth-child(3) { grid-column: 1; grid-row: 3; }
  body .zs-logos.zs-v-band .zs-logos__img:nth-child(4) { grid-column: 2; grid-row: 4; }
  body .zs-logos.zs-v-band .zs-logos__img:nth-child(5) { grid-column: 1; grid-row: 4; } }
